-- 005_courses: versioned training courses and optional regulation training category.
-- Every step has one read-only completion probe and one executable statement.

-- @step add_regulation_category_id
-- @check SELECT CASE WHEN EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'regulation' AND COLUMN_NAME = 'category_id' AND DATA_TYPE = 'bigint' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) THEN 1 ELSE 0 END AS complete;
ALTER TABLE `regulation` ADD COLUMN `category_id` BIGINT UNSIGNED NULL COMMENT '可选培训类别；独立于 legacy category 字符串' AFTER `category`;

-- @step add_regulation_category_index
-- @check SELECT CASE WHEN (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'regulation' AND INDEX_NAME = 'idx_regulation_category_id' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'category_id' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) = 1 THEN 1 ELSE 0 END AS complete;
ALTER TABLE `regulation` ADD KEY `idx_regulation_category_id` (`category_id`);

-- @step create_training_course
-- @check SELECT CASE WHEN EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'training_course' AND TABLE_TYPE = 'BASE TABLE' AND ENGINE = 'InnoDB' AND TABLE_COLLATION = 'utf8mb4_0900_ai_ci') AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'training_course') = 13 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'training_course' AND ((COLUMN_NAME = 'id' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'NO' AND EXTRA = 'auto_increment') OR (COLUMN_NAME = 'title' AND COLUMN_TYPE = 'varchar(255)' AND IS_NULLABLE = 'NO') OR (COLUMN_NAME = 'category_id' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'NO') OR (COLUMN_NAME = 'cover_asset_id' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'YES') OR (COLUMN_NAME IN ('description') AND DATA_TYPE = 'text' AND IS_NULLABLE = 'YES') OR (COLUMN_NAME = 'regulation_ids' AND DATA_TYPE = 'json' AND IS_NULLABLE = 'YES') OR (COLUMN_NAME = 'is_recommended' AND COLUMN_TYPE = 'tinyint unsigned' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = '0') OR (COLUMN_NAME = 'sort_order' AND COLUMN_TYPE = 'int' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = '0') OR (COLUMN_NAME = 'status' AND COLUMN_TYPE = 'varchar(32)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'draft') OR (COLUMN_NAME = 'created_by' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'NO') OR (COLUMN_NAME = 'published_at' AND COLUMN_TYPE = 'datetime(3)' AND IS_NULLABLE = 'YES') OR (COLUMN_NAME = 'created_at' AND COLUMN_TYPE = 'datetime(3)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'CURRENT_TIMESTAMP(3)') OR (COLUMN_NAME = 'updated_at' AND COLUMN_TYPE = 'datetime(3)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'CURRENT_TIMESTAMP(3)' AND EXTRA = 'DEFAULT_GENERATED on update CURRENT_TIMESTAMP(3)'))) = 13 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'training_course') = 5 THEN 1 ELSE 0 END AS complete;
CREATE TABLE IF NOT EXISTS `training_course` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `title` VARCHAR(255) NOT NULL COMMENT '课程标题', `category_id` BIGINT UNSIGNED NOT NULL COMMENT '培训类别', `cover_asset_id` BIGINT UNSIGNED NULL COMMENT 'course_cover 媒体资源', `description` TEXT NULL, `regulation_ids` JSON NULL COMMENT '可选制度信息关联；不构成学习或考试门槛', `is_recommended` TINYINT UNSIGNED NOT NULL DEFAULT 0, `sort_order` INT NOT NULL DEFAULT 0, `status` VARCHAR(32) NOT NULL DEFAULT 'draft' COMMENT 'draft / published / offline', `created_by` BIGINT UNSIGNED NOT NULL, `published_at` DATETIME(3) NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), KEY `idx_training_course_category_status` (`category_id`, `status`), KEY `idx_training_course_recommended_sort` (`is_recommended`, `sort_order`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='培训课程';

-- @step create_course_chapter
-- @check SELECT CASE WHEN EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'course_chapter' AND TABLE_TYPE = 'BASE TABLE' AND ENGINE = 'InnoDB' AND TABLE_COLLATION = 'utf8mb4_0900_ai_ci') AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'course_chapter') = 6 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'course_chapter' AND ((COLUMN_NAME = 'id' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'NO' AND EXTRA = 'auto_increment') OR (COLUMN_NAME = 'course_id' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'NO') OR (COLUMN_NAME = 'title' AND COLUMN_TYPE = 'varchar(255)' AND IS_NULLABLE = 'NO') OR (COLUMN_NAME = 'sort_order' AND COLUMN_TYPE = 'int' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = '0') OR (COLUMN_NAME = 'created_at' AND COLUMN_TYPE = 'datetime(3)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'CURRENT_TIMESTAMP(3)') OR (COLUMN_NAME = 'updated_at' AND COLUMN_TYPE = 'datetime(3)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'CURRENT_TIMESTAMP(3)' AND EXTRA = 'DEFAULT_GENERATED on update CURRENT_TIMESTAMP(3)'))) = 6 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'course_chapter') = 3 THEN 1 ELSE 0 END AS complete;
CREATE TABLE IF NOT EXISTS `course_chapter` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `course_id` BIGINT UNSIGNED NOT NULL, `title` VARCHAR(255) NOT NULL, `sort_order` INT NOT NULL DEFAULT 0, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), KEY `idx_course_chapter_course_sort` (`course_id`, `sort_order`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='课程章节';

-- @step create_course_lesson
-- @check SELECT CASE WHEN EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'course_lesson' AND TABLE_TYPE = 'BASE TABLE' AND ENGINE = 'InnoDB' AND TABLE_COLLATION = 'utf8mb4_0900_ai_ci') AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'course_lesson') = 10 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'course_lesson' AND ((COLUMN_NAME = 'id' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'NO' AND EXTRA = 'auto_increment') OR (COLUMN_NAME IN ('course_id', 'chapter_id') AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'NO') OR (COLUMN_NAME = 'title' AND COLUMN_TYPE = 'varchar(255)' AND IS_NULLABLE = 'NO') OR (COLUMN_NAME = 'lesson_type' AND COLUMN_TYPE = 'varchar(32)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'video') OR (COLUMN_NAME = 'is_required' AND COLUMN_TYPE = 'tinyint unsigned' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = '1') OR (COLUMN_NAME = 'sort_order' AND COLUMN_TYPE = 'int' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = '0') OR (COLUMN_NAME = 'current_version_id' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'YES') OR (COLUMN_NAME = 'created_at' AND COLUMN_TYPE = 'datetime(3)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'CURRENT_TIMESTAMP(3)') OR (COLUMN_NAME = 'updated_at' AND COLUMN_TYPE = 'datetime(3)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'CURRENT_TIMESTAMP(3)' AND EXTRA = 'DEFAULT_GENERATED on update CURRENT_TIMESTAMP(3)'))) = 10 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'course_lesson') = 4 THEN 1 ELSE 0 END AS complete;
CREATE TABLE IF NOT EXISTS `course_lesson` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `course_id` BIGINT UNSIGNED NOT NULL, `chapter_id` BIGINT UNSIGNED NOT NULL, `title` VARCHAR(255) NOT NULL, `lesson_type` VARCHAR(32) NOT NULL DEFAULT 'video' COMMENT '本期仅 video', `is_required` TINYINT UNSIGNED NOT NULL DEFAULT 1, `sort_order` INT NOT NULL DEFAULT 0, `current_version_id` BIGINT UNSIGNED NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), KEY `idx_course_lesson_course` (`course_id`), KEY `idx_course_lesson_chapter_sort` (`chapter_id`, `sort_order`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='课程课时';

-- @step create_lesson_version
-- @check SELECT CASE WHEN EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'lesson_version' AND TABLE_TYPE = 'BASE TABLE' AND ENGINE = 'InnoDB' AND TABLE_COLLATION = 'utf8mb4_0900_ai_ci') AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'lesson_version') = 7 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'lesson_version' AND ((COLUMN_NAME = 'id' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'NO' AND EXTRA = 'auto_increment') OR (COLUMN_NAME IN ('lesson_id', 'asset_id', 'duration_ms', 'created_by') AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'NO') OR (COLUMN_NAME = 'version_no' AND COLUMN_TYPE = 'int unsigned' AND IS_NULLABLE = 'NO') OR (COLUMN_NAME = 'created_at' AND COLUMN_TYPE = 'datetime(3)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'CURRENT_TIMESTAMP(3)'))) = 7 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'lesson_version') = 4 THEN 1 ELSE 0 END AS complete;
CREATE TABLE IF NOT EXISTS `lesson_version` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `lesson_id` BIGINT UNSIGNED NOT NULL, `version_no` INT UNSIGNED NOT NULL, `asset_id` BIGINT UNSIGNED NOT NULL COMMENT 'video 媒体资源', `duration_ms` BIGINT UNSIGNED NOT NULL COMMENT '服务端媒体探测时长快照', `created_by` BIGINT UNSIGNED NOT NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE KEY `uk_lesson_version_number` (`lesson_id`, `version_no`), KEY `idx_lesson_version_asset` (`asset_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='视频课时不可变内容版本';

-- @step register_course_permissions
-- @check SELECT CASE WHEN (SELECT COUNT(*) FROM `sys_permission` WHERE `code` IN ('courses:read', 'courses:write', 'courses:publish') AND `name` = CASE `code` WHEN 'courses:read' THEN '查看课程' WHEN 'courses:write' THEN '维护课程' WHEN 'courses:publish' THEN '发布课程' ELSE '' END) = 3 THEN 1 ELSE 0 END AS complete;
INSERT INTO `sys_permission` (`code`, `name`) VALUES ('courses:read', '查看课程'), ('courses:write', '维护课程'), ('courses:publish', '发布课程') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`);
